from itertools import combinations

def digit_sum(n):
    return sum(int(digit) for digit in str(n))

def satisfies_condition(subset):
    for a, b in combinations(subset, 2):
        if (a % b == 0) != (digit_sum(a) % digit_sum(b) == 0):
            return False
    return True

# Generate all subsets of size 17 from the set {1, ..., 100}
for subset in combinations(range(1, 101), 17):
    if satisfies_condition(subset):
        print(subset)
        break
